   157→      final SignedBeaconBlock signedBlock,
   158→      final BeaconState blockSlotState,
   159→      final IndexedAttestationCache indexedAttestationCache,
   160→      final BLSSignatureVerifier signatureVerifier,
   161→      final Optional<? extends OptimisticExecutionPayloadExecutor> payloadExecutor)
   162→      throws StateTransitionException {
   163→    try {
   164→      final BlockValidationResult preValidationResult =
   165→          validateBlockPreProcessing(blockSlotState, signedBlock, signatureVerifier);
   166→      if (!preValidationResult.isValid()) {
   167→        throw new BlockProcessingException(preValidationResult.getFailureReason());
   168→      }
   169→
