   178→
   179→      BlockValidationResult blockValidationResult =
   180→          validateBlockPostProcessing(
   181→              blockSlotState, signedBlock, postState, indexedAttestationCache, signatureVerifier);
   182→
   183→      if (!blockValidationResult.isValid()) {
   184→        throw new BlockProcessingException(blockValidationResult.getFailureReason());
   185→      }
   186→
   187→      return postState;
   188→    } catch (final IllegalArgumentException | BlockProcessingException e) {
   189→      LOG.warn(
   190→          String.format(
   191→              "State transition error while importing block %s (%s)",
   192→              signedBlock.getSlot(), signedBlock.getRoot()),
   193→          e);
   194→      throw new StateTransitionException(e);
   195→    }
   196→  }
