   198→  @CheckReturnValue
   199→  protected BlockValidationResult validateBlockPreProcessing(
   200→      final BeaconState preState,
   201→      final SignedBeaconBlock block,
   202→      final BLSSignatureVerifier signatureVerifier)
   203→      throws BlockProcessingException {
   204→    return BlockValidationResult.SUCCESSFUL;
   205→  }
   206→
   207→  /**
   208→   * Validate the given block. Checks signatures in the block and verifies stateRoot matches
   209→   * postState
   210→   *
   211→   * @param preState The preState to which the block is applied
   212→   * @param block The block being validated
   213→   * @param postState The post state resulting from processing the block on top of the preState
   214→   * @param indexedAttestationCache A cache for calculating indexed attestations
   215→   * @return A block validation result
   216→   */
   217→  @CheckReturnValue
   218→  private BlockValidationResult validateBlockPostProcessing(
   219→      final BeaconState preState,
   220→      final SignedBeaconBlock block,
   221→      final BeaconState postState,
   222→      final IndexedAttestationCache indexedAttestationCache,
   223→      final BLSSignatureVerifier signatureVerifier) {
   224→    return BlockValidationResult.allOf(
   225→        () -> verifyBlockSignatures(preState, block, indexedAttestationCache, signatureVerifier),
   226→        () -> validatePostState(postState, block));
   227→  }
   228→
   229→  @CheckReturnValue
   230→  protected BlockValidationResult verifyBlockSignatures(
   231→      final BeaconState preState,
   232→      final SignedBeaconBlock block,
   233→      final IndexedAttestationCache indexedAttestationCache,
   234→      final BLSSignatureVerifier signatureVerifier) {
   235→    BeaconBlock blockMessage = block.getMessage();
   236→    BeaconBlockBody blockBody = blockMessage.getBody();
   237→
   238→    return BlockValidationResult.allOf(
   239→        () -> verifyBlockSignature(preState, block, signatureVerifier),
   240→        () ->
   241→            verifyAttestationSignatures(
   242→                preState, blockBody.getAttestations(), signatureVerifier, indexedAttestationCache),
   243→        () -> verifyRandao(preState, blockMessage, signatureVerifier),
   244→        () ->
   245→            verifyProposerSlashings(preState, blockBody.getProposerSlashings(), signatureVerifier),
   246→        () -> verifyVoluntaryExits(preState, blockBody.getVoluntaryExits(), signatureVerifier));
   247→  }
   248→
   249→  @CheckReturnValue
   250→  private BlockValidationResult verifyBlockSignature(
   251→      final BeaconState state,
   252→      final SignedBeaconBlock block,
   253→      final BLSSignatureVerifier signatureVerifier) {
   254→    // this fetches the block proposer index hence we pass the block slot and not only the state
   255→    final int proposerIndex = beaconStateAccessors.getBeaconProposerIndex(state, block.getSlot());
   256→    final Optional<BLSPublicKey> proposerPublicKey =
   257→        beaconStateAccessors.getValidatorPubKey(state, UInt64.valueOf(proposerIndex));
   258→    if (proposerPublicKey.isEmpty()) {
   259→      return BlockValidationResult.failed("Public key not found for validator " + proposerIndex);
   260→    }
   261→    final Bytes signingRoot =
   262→        miscHelpers.computeSigningRoot(
   263→            block.getMessage(), getDomain(state, Domain.BEACON_PROPOSER));
   264→    if (!signatureVerifier.verify(proposerPublicKey.get(), signingRoot, block.getSignature())) {
   265→      return BlockValidationResult.failed("Invalid block signature: " + block);
   266→    }
   267→    return BlockValidationResult.SUCCESSFUL;
   268→  }
   269→
   270→  private Bytes32 getDomain(final BeaconState state, final Bytes4 beaconProposer) {
   271→    return beaconStateAccessors.getDomain(
   272→        state.getForkInfo(), beaconProposer, beaconStateAccessors.getCurrentEpoch(state));
   273→  }
   274→
   275→  @CheckReturnValue
   276→  private BlockValidationResult validatePostState(
   277→      final BeaconState postState, final SignedBeaconBlock block) {
   278→    if (!block.getMessage().getStateRoot().equals(postState.hashTreeRoot())) {
   279→      return BlockValidationResult.failed(
   280→          "Block state root does NOT match the calculated state root!\n"
   281→              + "Block state root: "
   282→              + block.getMessage().getStateRoot().toHexString()
   283→              + "\n  New state root: "
   284→              + postState.hashTreeRoot().toHexString()
   285→              + "\n block proposer: "
   286→              + block.getProposerIndex());
   287→    } else {
   288→      return BlockValidationResult.SUCCESSFUL;
   289→    }
   290→  }
