   292→  @Override
   293→  @CheckReturnValue
   294→  public Optional<OperationInvalidReason> validateAttestation(
   295→      final BeaconState state, final AttestationData data) {
   296→    return operationValidator.validateAttestationData(state.getFork(), state, data);
   297→  }
