   299→  protected void assertAttestationValid(
   300→      final MutableBeaconState state, final Attestation attestation) {
   301→    final AttestationData data = attestation.getData();
   302→
   303→    final Optional<OperationInvalidReason> invalidReason = validateAttestation(state, data);
   304→    checkArgument(
   305→        invalidReason.isEmpty(),
   306→        "process_attestations: %s",
   307→        invalidReason.map(OperationInvalidReason::describe).orElse(""));
   308→
   309→    IntList committee =
   310→        beaconStateAccessors.getBeaconCommittee(state, data.getSlot(), data.getIndex());
   311→    checkArgument(
   312→        attestation.getAggregationBits().size() == committee.size(),
   313→        "process_attestations: Attestation aggregation bits and committee don't have the same length - committee "
   314→            + committee.size()
   315→            + ", aggregation bits "
   316→            + attestation.getAggregationBits().size());
   317→  }
