   319→  @Override
   320→  public BeaconState processUnsignedBlock(
   321→      final BeaconState preState,
   322→      final BeaconBlock block,
   323→      final IndexedAttestationCache indexedAttestationCache,
   324→      final BLSSignatureVerifier signatureVerifier,
   325→      final Optional<? extends OptimisticExecutionPayloadExecutor> payloadExecutor)
   326→      throws BlockProcessingException {
   327→    return preState.updated(
   328→        state -> {
   329→          processBlock(state, block, indexedAttestationCache, signatureVerifier, payloadExecutor);
   330→          BeaconStateCache.getSlotCaches(state).onBlockProcessed();
   331→        });
